void kernel_doitgen(int nr, int nq, int np,
                     DATA_TYPE POLYBENCH_3D(A, NR, NQ, NP, nr, nq, np),
                     DATA_TYPE POLYBENCH_2D(C4, NP, NP, np, np),
                     DATA_TYPE POLYBENCH_1D(sum, NP, np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      for (p = 0; p < _PB_NP; p++) {
        sum[p] = SCALAR_VAL(0.0);
      }

      for (s = 0; s < _PB_NP; s++) {
        const double a_val = A[r][q][s];
        int p = 0;
        while (p < _PB_NP) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NP - p));
          vfloat64m1_t vsum = __riscv_vle64_v_f64m1(&sum[p], vl);
          vfloat64m1_t vc4  = __riscv_vle64_v_f64m1(&C4[s][p], vl);
          vfloat64m1_t va   = __riscv_vfmv_v_f_f64m1(a_val, vl);
          vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vc4, vl);
          vsum = __riscv_vfadd_vv_f64m1(vsum, vprod, vl);
          __riscv_vse64_v_f64m1(&sum[p], vsum, vl);
          p += (int)vl;
        }
      }

      for (p = 0; p < _PB_NP; p++) {
        A[r][q][p] = sum[p];
      }
    }
  }
#pragma endscop
}

