static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];

      for (i = 1; i < _PB_NX; i++)
	{
	  int j = 0;
	  for (; j + 3 < _PB_NY; j += 4)
	    {
	    ey[i][j]     = ey[i][j]     - SCALAR_VAL(0.5)*(hz[i][j]     - hz[i-1][j]);
	    ey[i][j + 1] = ey[i][j + 1] - SCALAR_VAL(0.5)*(hz[i][j + 1] - hz[i-1][j + 1]);
	    ey[i][j + 2] = ey[i][j + 2] - SCALAR_VAL(0.5)*(hz[i][j + 2] - hz[i-1][j + 2]);
	    ey[i][j + 3] = ey[i][j + 3] - SCALAR_VAL(0.5)*(hz[i][j + 3] - hz[i-1][j + 3]);
	  }
	  for (; j < _PB_NY; j++)
	    ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
	}

      for (i = 0; i < _PB_NX; i++)
	{
	  int j = 1;
